    25	        BigDecimal discount,
    26	        BigDecimal total,
    27	        String text) {
    28	
    29	    public ReservationReceipt(Reservation reservation, Room room) {
    30	        this(reservation, room, selectGenerator(reservation));
    31	    }
    32	
    33	    private ReservationReceipt(Reservation reservation, Room room, DocumentGenerator generator) {
    34	        this(
    35	                generator.title(),
    36	                reservation.id(),
    37	                reservation.guest().name(),
    38	                reservation.guest().cpf(),
    39	                reservation.guest().companyCnpj(),
    40	                reservation.guest().companyName(),
    41	                reservation.guest().passport(),
    42	                reservation.guest().country(),
    43	                room.number(),
    44	                room.type(),
    45	                reservation.checkIn(),
    46	                reservation.checkOut(),
    47	                reservation.price().nights(),
    48	                reservation.price().subtotal(),
    49	                reservation.price().discount(),
    50	                reservation.price().total(),
    51	                generator.formatDocument(
    52	                        reservation.id(),
    53	                        reservation.guest(),
    54	                        room,
    55	                        reservation.checkIn(),
    56	                        reservation.checkOut(),
    57	                        reservation.price()));
    58	    }
    59	
    60	    private static DocumentGenerator selectGenerator(Reservation reservation) {
    61	        if (reservation.guest().cpf() != null) {
    62	            return new IndividualDocumentGenerator();
    63	        }
    64	        if (reservation.guest().companyCnpj() != null) {
    65	            return new CompanyDocumentGenerator();
    66	        }
    67	        return new ForeignDocumentGenerator();
    68	    }
    69	}
