130	        boolean hasPassport = !isBlank(body.guestPassport()) && !isBlank(body.guestCountry());
131	
132	        int identificationCount = (hasCpf ? 1 : 0) + (hasCompany ? 1 : 0) + (hasPassport ? 1 : 0);
133	        if (identificationCount != 1) {
134	            throw new HotelException(ErrorCode.INVALID_REQUEST,
135	                    "exactly one guest identification is required: guestCpf, or companyCnpj with companyName, "
136	                            + "or guestPassport with guestCountry");
137	        }
138	
139	        Guest guest;
140	        if (hasCpf) {
141	            guest = Guest.withCpf(body.guestName(), body.guestEmail(), body.guestCpf());
142	        } else if (hasCompany) {
143	            guest = Guest.withCompany(body.guestName(), body.guestEmail(), body.companyCnpj(), body.companyName());
144	        } else {
145	            guest = Guest.withPassport(body.guestName(), body.guestEmail(), body.guestPassport(), body.guestCountry());
146	        }
147	
148	        return new NewReservation(
149	                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
150	    }
151	
152	    private static long reservationId(Context ctx) {
153	        String id = ctx.pathParam("id");
154	        try {
155	            return Long.parseLong(id);
156	        } catch (NumberFormatException notANumber) {
157	            throw new HotelException(ErrorCode.RESERVATION_NOT_FOUND, "reservation " + id + " does not exist");
158	        }
159	    }
160	
161	    private static LocalDate readDate(Context ctx) {
162	        String date = requiredQueryParam(ctx, "date");
163	        try {
164	            return LocalDate.parse(date);
165	        } catch (DateTimeParseException badDate) {
166	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + date + "' is not a date (yyyy-MM-dd)");
167	        }
168	    }
169	
170	    private static YearMonth readMonth(Context ctx) {
171	        String month = requiredQueryParam(ctx, "month");
172	        try {
173	            return YearMonth.parse(month);
174	        } catch (DateTimeParseException badMonth) {
175	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + month + "' is not a month (yyyy-MM)");
176	        }
177	    }
178	
179	    private static String requiredQueryParam(Context ctx, String name) {
180	        String value = ctx.queryParam(name);
181	        if (value == null) {
182	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the query parameter '" + name + "' is required");
183	        }
184	        return value;
185	    }
186	
187	    private static boolean isBlank(String text) {
188	        return text == null || text.isBlank();
189	    }
